<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { api, auth, preferences, paths, displayDate } from '../api'
const items = ref([]), recommendations = ref(null), history = ref([]), selectedRun = ref(null), path = ref(''), city = ref(''), q = ref(''), expired = ref(false), error = ref(''), busy = ref(false)
const router = useRouter(), decisionSelection = ref([])
function selectForComparison(id) { if (decisionSelection.value.includes(id)) decisionSelection.value = decisionSelection.value.filter(n=>n!==id); else if (decisionSelection.value.length < 6) decisionSelection.value.push(id); else error.value = '一次最多选择 6 个机会，请先取消一个。' }
function compareSelected() { router.push({path:'/decisions',query: decisionSelection.value.length ? {ids:decisionSelection.value.join(',')} : {}}) }
const grouped = computed(() => Object.entries(paths).filter(([p]) => ['employment','postgraduate','civil_service','public_institution','internship'].includes(p)).map(([p,label]) => ({ label, items: recommendations.value?.results.filter(r => r.opportunity.path === p) || [] })).filter(g => g.items.length))
async function load() {
  error.value = ''
  const params = new URLSearchParams({ data_kind: preferences.demo ? 'demo' : 'public', q: q.value, include_expired: String(expired.value) })
  if (path.value) params.set('path', path.value)
  if (city.value) params.set('city', city.value)
  try { items.value = await api(`/opportunities?${params}`); if(auth.user) history.value = await api('/recommendations/history') }
  catch(e) { error.value = e.message }
}
async function refreshRecommendations() {
  error.value = ''; busy.value = true
  try { recommendations.value = await api(`/recommendations?data_kind=${preferences.demo ? 'demo' : 'public'}`, { method: 'POST' }); history.value = await api('/recommendations/history') }
  catch(e) { error.value = e.message } finally { busy.value = false }
}
watch(() => preferences.demo, () => { recommendations.value = null; selectedRun.value = null; decisionSelection.value = []; load() })
onMounted(load)
</script>
<template><div class="page-heading"><div><div class="eyebrow">EXPLORE OPPORTUNITIES</div><h1>下一站，有更多选择<span class="heading-dot">.</span></h1><p>分路径探索机会，核对原文条件，再做自己的决定。</p></div><button v-if="auth.user" class="button" :disabled="busy" @click="refreshRecommendations">{{ busy ? '生成中…' : '生成我的推荐 ↗' }}</button><RouterLink v-else class="button" to="/login">登录获取画像推荐</RouterLink></div><div v-if="preferences.demo" class="alert demo">所有机会均为模拟示例，不可用于实际报名或投递。</div><div v-if="error" class="alert error" role="alert">{{ error }}</div><section v-if="recommendations" class="panel"><div class="panel-heading"><h2>当前画像的参考机会</h2><span class="tag">画像 V{{ recommendations.profile_version }}</span></div><p class="muted">排序分只使用已观测的技能、城市与专业条件；信息不足时不评分。不同路径分别展示，不代表录用概率或人生优先级。</p><div v-if="!recommendations.results.length" class="empty">暂无符合当前结构化条件的机会；可完善画像或等待新公告。</div><div v-for="group in grouped" :key="group.label" class="recommendation-group"><h3>{{ group.label }}</h3><article v-for="r in group.items" :key="r.opportunity.id" class="recommendation-card"><div><h3>{{ r.opportunity.title }}</h3><p>{{ r.reasons.join(' · ') || '信息不足，作为近期相关机会展示' }}</p><p v-if="r.skill_gaps.length">待补充技能：{{ r.skill_gaps.join('、') }}</p><p v-if="r.skills_unknown">技能未填写，暂不判断技能差距</p><span v-if="r.needs_review" class="tag amber">资格条件需要核对</span></div><div class="score"><strong>{{ r.score ?? '—' }}</strong><small>{{ r.score === null ? '信息不足' : '参考排序分' }}</small></div></article></div><details class="history-details"><summary>查看历史推荐（{{ history.length }} 次）</summary><select v-model="selectedRun"><option :value="null">选择一次已保存的推荐</option><option v-for="h in history" :key="h.id" :value="h">#{{ h.id }} · 画像 V{{ h.profile_version }} · {{ displayDate(h.generated_at) }} · {{ h.data_kind === 'demo' ? '模拟' : '公开机会' }}</option></select><div v-if="selectedRun"><p>模型：{{ selectedRun.model_version }}。历史内容来自生成时的机会版本，不随新公告覆盖。</p><div v-for="r in selectedRun.results" :key="r.opportunity.id" class="history-row">{{ r.opportunity.title }} · 机会 V{{ r.opportunity_version }} · {{ r.score ?? '信息不足' }}</div></div></details></section><section v-if="auth.user" class="panel shortlist-toolbar"><div><h2>从找到机会，到认真比较</h2><p class="muted">勾选最多 6 个机会，比较条件与技能差距，并生成你的行动清单。</p></div><button class="button small" @click="compareSelected">{{ decisionSelection.length ? `比较已选 ${decisionSelection.length} 项 →` : '进入辅助决策 →' }}</button></section><form class="filterbar" @submit.prevent="load"><label>路径<select v-model="path"><option value="">全部发展路径</option><option v-for="p in ['employment','postgraduate','civil_service','public_institution','internship']" :key="p" :value="p">{{ paths[p] }}</option></select></label><label>城市<input v-model="city" placeholder="城市名称"></label><label class="source-filter">关键词<input v-model="q" placeholder="机会、单位或描述"></label><label class="choice"><input v-model="expired" type="checkbox">包含过期</label><button class="button small">筛选</button></form><div v-if="!items.length" class="empty large"><span>↗</span><h3>暂无符合条件的机会</h3><p>真实公告需由管理员核验录入，或切换到模拟演示。</p></div><div class="opportunity-grid"><article v-for="o in items" :key="o.id" class="panel opportunity-card"><div class="panel-heading"><span class="tag">{{ paths[o.path] }}</span><span v-if="o.expired" class="tag amber">已过期</span><span v-else class="muted">V{{ o.version }}</span></div><label v-if="auth.user" class="choice compare-checkbox"><input type="checkbox" :checked="decisionSelection.includes(o.id)" :disabled="!decisionSelection.includes(o.id) && decisionSelection.length >= 6" @change="selectForComparison(o.id)">加入比较</label><h2>{{ o.title }}</h2><p>{{ o.organization }} · {{ o.city || '城市待核对' }}</p><p class="description">{{ o.description }}</p><div class="skill-tags"><span v-for="s in o.skills" :key="s" class="tag neutral">{{ s }}</span></div><p class="muted">专业：{{ o.majors.join('、') || '需要核对' }}<br>截止日期：{{ displayDate(o.deadline) }}</p><div class="card-footer"><span class="muted">{{ o.data_kind === 'demo' ? '模拟数据' : '公开来源' }}</span><a :href="o.source_url" target="_blank" rel="noopener noreferrer">查看原文 ↗</a></div></article></div></template>
